instagram_search.script:
(async () => {
            try { return { rows: await ((async () => {
  const query = "SKRILLER_QUERY_ARGUMENT_89f4";
  const limit = 987654321;

    async function readInstagramJson(response, label) {
        let text;
        try { text = await response.text(); }
        catch { throw new Error(label + ' response body could not be read'); }
        let data;
        try { data = JSON.parse(text); }
        catch {
            const html = /^\s*</.test(text);
            const challenge = html && /challenge_required|checkpoint|captcha|login_required|accounts\/login/i.test(text);
            const error = new Error(label + (html ? ' returned HTML instead of JSON' : ' returned invalid JSON') + ' (HTTP ' + response.status + ')');
            if (challenge) error.code = 'AUTH_REQUIRED';
            throw error;
        }
        if (!data || typeof data !== 'object' || Array.isArray(data)) throw new Error(label + ' returned malformed JSON');
        if (data.status === 'fail' || data.message === 'login_required' || data.challenge) {
            const error = new Error(label + ' returned an API failure');
            if (data.challenge || /login_required|challenge_required|checkpoint_required/.test(String(data.message || ''))) error.code = 'AUTH_REQUIRED';
            throw error;
        }
        return data;
    }

  const res = await fetch(
    'https://www.instagram.com/web/search/topsearch/?query=' + encodeURIComponent(query) + '&context=user',
    {
      credentials: 'include',
      headers: { 'X-IG-App-ID': '936619743392459' }
    }
  );
  if (!res.ok) throw new Error('Instagram search failed: HTTP ' + res.status);
  const data = await readInstagramJson(res, 'Instagram search');
  if (!Array.isArray(data.users)) throw new Error('Instagram search returned malformed users');
  const users = data.users.filter((item) => item.user?.is_private === false).slice(0, limit);
  return users.map((item, i) => ({
    rank: i + 1,
    username: item.user?.username || '',
    name: item.user?.full_name || '',
    verified: typeof item.user?.is_verified === 'boolean' ? item.user.is_verified : null,
    private: false,
    avatar_url: typeof item.user?.profile_pic_url === 'string' && item.user.profile_pic_url.startsWith('https://') ? item.user.profile_pic_url : '',
    url: 'https://www.instagram.com/' + (item.user?.username || ''),
  }));
})()
) }; }
            catch (error) { return { failure: { code: error.code, message: String(error.message || error) } }; }
        })()

instagram_profile.script:
(async () => {
            try { return { rows: await ((async () => {
  const username = "SKRILLER_PROFILE_ARGUMENT_89f4";
  const opts = { credentials: 'include', headers: { 'X-IG-App-ID': '936619743392459' } };
  function normalizeInstagramUserId(value, label) {
    const id = typeof value === 'number' ? String(value) : (typeof value === 'string' ? value.trim() : '');
    if (!/^\d+$/.test(id)) throw new Error(label);
    return id;
  }

    async function readInstagramJson(response, label) {
        let text;
        try { text = await response.text(); }
        catch { throw new Error(label + ' response body could not be read'); }
        let data;
        try { data = JSON.parse(text); }
        catch {
            const html = /^\s*</.test(text);
            const challenge = html && /challenge_required|checkpoint|captcha|login_required|accounts\/login/i.test(text);
            const error = new Error(label + (html ? ' returned HTML instead of JSON' : ' returned invalid JSON') + ' (HTTP ' + response.status + ')');
            if (challenge) error.code = 'AUTH_REQUIRED';
            throw error;
        }
        if (!data || typeof data !== 'object' || Array.isArray(data)) throw new Error(label + ' returned malformed JSON');
        if (data.status === 'fail' || data.message === 'login_required' || data.challenge) {
            const error = new Error(label + ' returned an API failure');
            if (data.challenge || /login_required|challenge_required|checkpoint_required/.test(String(data.message || ''))) error.code = 'AUTH_REQUIRED';
            throw error;
        }
        return data;
    }

  function throwInstagramHttpError(response, label) {
    if (response.status === 404) throw new Error('User not found: ' + username);
    if (response.status === 401 || response.status === 403) {
      throw new Error('HTTP ' + response.status + ' - make sure you are logged in to Instagram');
    }
    throw new Error(label + ' failed: HTTP ' + response.status);
  }
  function mapProfileUser(u, countFields) {
    if (!u || typeof u !== 'object' || typeof u.username !== 'string' || !u.username.trim()) {
      throw new Error('Instagram profile returned malformed user payload for: ' + username);
    }
    if (u.username.toLowerCase() !== String(username).toLowerCase()) {
      throw new Error('Instagram profile did not match the requested username');
    }
    if (u.is_private !== false) {
      throw new Error('Instagram profile requires an explicitly public account');
    }
    return {
      private: false,
      username: u.username,
      name: typeof u.full_name === 'string' ? u.full_name : '',
      bio: (typeof u.biography === 'string' ? u.biography : '').replace(/\n/g, ' ').substring(0, 120),
      followers: countFields.followers(u),
      following: countFields.following(u),
      posts: countFields.posts(u),
      verified: typeof u.is_verified === 'boolean' ? u.is_verified : null,
      // Signed CDN URL: expires after a while, so download it rather than hotlink it.
      avatar_url: profilePicUrl(u),
    };
  }
  function profilePicUrl(u) {
    const candidates = [u.profile_pic_url_hd, u.hd_profile_pic_url_info?.url, u.profile_pic_url];
    return candidates.find((v) => typeof v === 'string' && v.startsWith('https://')) || '';
  }
  const r1 = await fetch(
    'https://www.instagram.com/api/v1/users/web_profile_info/?username=' + encodeURIComponent(username),
    opts
  );
  if (r1.status === 404) throw new Error('User not found: ' + username);
  if (!r1.ok && r1.status !== 400) throwInstagramHttpError(r1, 'Instagram web_profile_info');
  if (r1.ok) {
    const data = await readInstagramJson(r1, 'Instagram web_profile_info');
    const u = data?.data?.user;
    return [mapProfileUser(u, {
      followers: (user) => user.edge_followed_by?.count ?? null,
      following: (user) => user.edge_follow?.count ?? null,
      posts: (user) => user.edge_owner_to_timeline_media?.count ?? null,
    })];
  }
  // web_profile_info answers HTTP 400 for business/professional accounts.
  // Resolve the id via feed-by-username (its root user.pk is the profile
  // owner), then read the full profile from users/<id>/info/.
  const r2 = await fetch(
    'https://www.instagram.com/api/v1/feed/user/' + encodeURIComponent(username) + '/username/?count=1',
    opts
  );
  if (!r2.ok) throwInstagramHttpError(r2, 'Instagram feed-by-username');
  const pk = normalizeInstagramUserId((await readInstagramJson(r2, 'Instagram feed-by-username'))?.user?.pk, 'Instagram feed returned no valid profile owner for: ' + username);
  const r3 = await fetch('https://www.instagram.com/api/v1/users/' + pk + '/info/', opts);
  if (!r3.ok) throwInstagramHttpError(r3, 'Instagram users info');
  const u = (await readInstagramJson(r3, 'Instagram users info'))?.user;
  return [mapProfileUser(u, {
    followers: (user) => user.follower_count ?? null,
    following: (user) => user.following_count ?? null,
    posts: (user) => user.media_count ?? null,
  })];
})()
) }; }
            catch (error) { return { failure: { code: error.code, message: String(error.message || error) } }; }
        })()

facebook_search.script:
(() => {
    const limit = 50;

    function clean(value) {
      return String(value || '')
        .replace(/[\u200b-\u200f\u202a-\u202e\u2060\ufeff]/g, '')
        .replace(/\s+/g, ' ')
        .trim();
    }

    // FB anti-scrape obfuscation: long spaceless digit tokens and spaced
    // single-char strings ("a b c d e"). Real titles never look like this.
    function isObfuscated(text) {
      if (!text) return true;
      if (/^\d{8,}$/.test(text)) return true;
      if (/^(?:\S ){4,}\S$/.test(text) && text.replace(/\s/g, '').length <= 12) return true;
      return false;
    }

    function isEntityHref(href) {
      if (!href) return false;
      let u;
      try { u = new URL(href, 'https://www.facebook.com'); } catch (e) { return false; }
      // drop hidden-domain .com spam — real results stay on facebook.com
      if (!/(^|\.)facebook\.com$/i.test(u.hostname)) return false;
      // l.facebook.com / lm.facebook.com only wrap outbound links (/l.php?u=…);
      // they are redirect shims, never search entities.
      if (/^lm?\.facebook\.com$/i.test(u.hostname)) return false;
      const p = u.pathname;
      if (/^\/search(\/|$)/i.test(p)) return false;                  // decoy links back to search (incl. bare /search)
      // chrome / non-result destinations that the catch-all below would keep
      if (/^\/(login|checkpoint|help|policies|privacy|settings|bookmarks|messages|notifications|marketplace|gaming|friends|requests|saved|me)\b/i.test(p)) return false;
      return /^\/(profile\.php|photo\.php|groups\/|events\/|watch\/|reel\/|pages\/|permalink\.php|story\.php|[^/]+\/posts\/|[^/]+\/videos\/|[A-Za-z0-9.\-]{2,}\/?$)/i.test(p);
    }

    // Query-identity destinations (permalink.php?story_fbid=…, story.php,
    // photo.php?fbid=…, watch/?v=…) collapse into a single row when the query is
    // dropped — different posts/videos share the same pathname. Keep the identity
    // params, but only those: FB appends per-render tracking nonces (__cft__,
    // __tn__, ref) that would otherwise defeat dedup by making the same post look
    // unique on every render.
    function entityKey(u) {
      const p = u.pathname.toLowerCase();
      let identityParams = [];
      if (p === '/profile.php') identityParams = ['id'];
      else if (p === '/permalink.php' || p === '/story.php') {
        identityParams = ['story_fbid', 'story_id', 'fbid', 'id'];
      } else if (p === '/photo.php') identityParams = ['fbid', 'id'];
      else if (p === '/watch' || p === '/watch/') identityParams = ['v'];
      const ids = identityParams
        .filter((k) => u.searchParams.has(k))
        .map((k) => k + '=' + u.searchParams.get(k));
      return ids.length ? (u.origin + u.pathname + '?' + ids.join('&')) : (u.origin + u.pathname);
    }

    function isAuthPage() {
      const path = window.location && window.location.pathname ? window.location.pathname : '';
      const body = clean(document.body && document.body.textContent);
      return /^\/(login|checkpoint)(\/|$|\.php)/.test(path)
        || /^(Log in to Facebook|Facebook登录|登录 Facebook)/i.test(body)
        || /You must log in to continue/i.test(body);
    }

    if (isAuthPage()) return { status: 'auth', rows: [], diagnostics: {} };

    const feed = document.querySelector('[role="feed"]')
      || document.querySelector('[role="main"]')
      || document.body;
    const anchors = Array.from(feed.querySelectorAll('a[href]'));
    const seen = new Set();
    const rows = [];
    for (const a of anchors) {
      const rawHref = a.href || a.getAttribute('href') || '';
      if (!isEntityHref(rawHref)) continue;
      let key;
      try { const u = new URL(rawHref, 'https://www.facebook.com'); key = entityKey(u); }
      catch (e) { key = rawHref.split('#')[0]; }
      if (seen.has(key)) continue;

      const title = clean(a.textContent).substring(0, 80);
      if (!title || isObfuscated(title)) continue;

      // climb a few levels for the surrounding card text
      let card = a;
      for (let i = 0; i < 4 && card.parentElement; i += 1) {
        card = card.parentElement;
        if (clean(card.textContent).length > title.length + 20) break;
      }
      const text = clean(card.textContent).substring(0, 150);
      if (isObfuscated(text)) continue;

      seen.add(key);
      rows.push({ index: rows.length + 1, title, text, url: key });
      if (rows.length >= limit) break;
    }

    return {
      status: rows.length ? 'ok' : 'no_rows',
      rows,
      diagnostics: {
        feedFound: !!document.querySelector('[role="feed"]'),
        anchorCount: anchors.length,
        mainTextLength: clean((document.querySelector('[role="main"]') || {}).textContent).length,
      },
    };
  })()

facebook_profile.script:
(() => {
  const username = "SKRILLER_PROFILE_ARGUMENT_89f4";
  const main = document.querySelector('[role="main"]') || document;
  const clean = (value) => String(value || '').replace(/\s+/g, ' ').trim();
  const h1 = main.querySelector('h1');
  let name = clean(h1 && h1.textContent);

  // Facebook's current profile header no longer uses an h1. The profile-avatar
  // link carries the display name on both the link and its role=img child.
  // Scope this fallback to the requested profile path so page chrome cannot win.
  if (!name) {
    const requestedPrefix = '/' + String(username).toLowerCase() + '/';
    const profileMediaLink = Array.from(main.querySelectorAll('a[aria-label][href]')).find((link) => {
      const href = link.getAttribute('href') || '';
      let path = '';
      try { path = new URL(href, window.location.href).pathname.toLowerCase(); } catch {}
      const image = link.querySelector('[role="img"][aria-label]');
      return path.startsWith(requestedPrefix)
        && image
        && clean(link.getAttribute('aria-label')) === clean(image.getAttribute('aria-label'));
    });
    name = clean(profileMediaLink && profileMediaLink.getAttribute('aria-label'));
  }

  // Scope relationship links to the profile main region. Global navigation also
  // contains /friends and previously produced empty or generic chrome text.
  const links = Array.from(main.querySelectorAll('a[href]'));
  const hasProfilePath = (link, suffix) => {
    try {
      const path = new URL(link.getAttribute('href') || '', window.location.href).pathname
        .replace(/\/+$/, '')
        .toLowerCase();
      return path === '/' + String(username).toLowerCase() + suffix;
    } catch { return false; }
  };
  const friendsLink = links.find((a) => hasProfilePath(a, '/friends'));
  const followersLink = links.find((a) => hasProfilePath(a, '/followers'));

  return [{
    name: name,
    username,
    friends: friendsLink ? clean(friendsLink.textContent) : '-',
    followers: followersLink ? clean(followersLink.textContent) : '-',
    url: window.location.href,
  }];
})()
